import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    idx = 0

    n = int(input_data[idx]); idx += 1
    m = int(input_data[idx]); idx += 1

    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(input_data[idx]); idx += 1
        v = int(input_data[idx]); idx += 1
        adj[u].append(v)
        adj[v].append(u)

    s = int(input_data[idx]); idx += 1
    b = int(input_data[idx]); idx += 1
    k = int(input_data[idx]); idx += 1
    h = int(input_data[idx]); idx += 1

    spaceships = []
    for _ in range(s):
        x = int(input_data[idx]); idx += 1
        a = int(input_data[idx]); idx += 1
        f = int(input_data[idx]); idx += 1
        spaceships.append((x, a, f))

    bases = []
    for _ in range(b):
        x = int(input_data[idx]); idx += 1
            d = int(input_data[idx]); idx += 1
        bases.append((x, d))

    dist = {}
    for i in range(1, n + 1):
        d = [-1] * (n + 1)
        q = deque([i])
        d[i] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if d[v] == -1:
                    d[v] = d[u] + 1
                    q.append(v)
        for j in range(1, n + 1):
            if d[j] != -1:
                dist[(i, j)] = d[j]

    can_attack = []
    for i, (sx, sa, sf) in enumerate(spaceships):
        for j, (bx, bd) in enumerate(bases):
            d_val = dist.get((sx, bx), float('inf'))
            if sa >= bd and sf >= d_val:
                can_attack.append((i, j))

    match_base = [-1] * b
    def dfs(u, visited):
        for _, v in can_attack:
            if u != v:
                continue
        for _, v in can_attack:
            if u != v or v < 0:
                continue
        return False

    def dfs(u, visited):
        for _, v in can_attack[u]:
            if visited[v]:
                continue
            visited[v] = True
            if match_base[v] < 0 or dfs(match_base[v], visited):
                match_base[v] = u
                return True
        return False

    can_attack_list = [[] for _ in range(s)]
    for i, j in can_attack:
        can_attack_list[i].append(j)

    matches = 0
    for i in range(s):
        visited = [False] * b
        if dfs(i, visited):
            matches += 1

    max_real_attacks = matches
    min_dummy_needed = s - max_real_attacks

    cost_real = max_real_attacks * k
    cost_dummy = min_dummy_needed * h

    ans = min(cost_real + cost_dummy, s * h)

    print(ans)

solve()
